    /*
     * Editing a tbl_voucher
     */
    function edit($id)
    {   
        // check if the tbl_voucher exists before trying to edit it
        $data['tbl_voucher'] = $this->Tbl_voucher_model->get_tbl_voucher($id);
        
        if(isset($data['tbl_voucher']['id']))
        {
            $this->load->library('form_validation');

			$this->form_validation->set_rules('PartyId','PartyId','required|integer');
			$this->form_validation->set_rules('Collect_By','Collect By','required|integer');
			$this->form_validation->set_rules('Date','Date','required');
